import React from 'react';import{createRoot}from'react-dom/client';import{MemoryRouter,Routes,Route,Link,useLocation}from'react-router-dom';import{ToolAvailabilityProvider,useToolAvailability}from'../../../src/hooks/useToolAvailability.jsx';import{ToolAvailabilityConsole}from'../../../src/modules/developer/ToolAvailabilityConsole.jsx';import{ToolAvailabilityGate}from'../../../src/modules/ToolAvailabilityGate.jsx';import{permittedModules}from'../../../src/modules/registry.js';import'../../../src/styles/tokens.css';import'../../../src/styles/base.css';import'../../../src/styles/primitives.css';
function Test(){const [developer,setDeveloper]=React.useState(true);const availability=useToolAvailability();const permissions={permissionSource:'server',canAccessDeveloper:developer,canEstimate:true,toolAvailability:availability,canAccessAddon:()=>true};return <main style={{padding:20}}><label><input type="checkbox" checked={developer} onChange={e=>setDeveloper(e.target.checked)}/>Developer fixture</label><nav aria-label="Standard navigation" style={{display:"flex",flexWrap:"wrap"}}>{permittedModules(permissions).map(m=><Link style={{margin:8}} key={m.key} to={m.path}>{m.label}</Link>)}</nav><Link to="/estimates">Direct estimator link</Link><Routes><Route path="/developer" element={<ToolAvailabilityConsole permissions={permissions}/>}/><Route path="*" element={<ToolAvailabilityGate permissions={permissions}><><h1>Tool workspace content</h1><Link to="/estimates/assemblies">Internal estimator page</Link></></ToolAvailabilityGate>}/></Routes></main>};createRoot(document.getElementById('root')).render(<MemoryRouter initialEntries={['/developer']}><ToolAvailabilityProvider><Test/></ToolAvailabilityProvider></MemoryRouter>);
